func (q *Queries) ListRecurringCalendarEventsByRange(ctx context.Context, arg ListRecurringCalendarEventsByRangeParams) ([]ListRecurringCalendarEventsByRangeRow, error) {
	rows, err := q.db.QueryContext(ctx, listRecurringCalendarEventsByRange, arg.CalendarID, arg.StartAt, arg.RecurrenceEnd)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListRecurringCalendarEventsByRangeRow{}
	for rows.Next() {
		var i ListRecurringCalendarEventsByRangeRow
		if err := rows.Scan(
			&i.PublicID,
			&i.Kind,
			&i.Visibility,
			&i.ShowAs,
			&i.Title,
			&i.AllDay,
			&i.StartAt,
			&i.EndAt,
			&i.Timezone,
			&i.Location,
			&i.Memo,
			&i.Url,
			&i.OwnerUserID,
			&i.CreatedByUserID,
			&i.BlockLabel,
			&i.RecurrenceRule,
			&i.RecurrenceEnd,
			&i.RecurrenceExceptions,
			&i.NotificationOffset,
			&i.TaskID,
			&i.UpdatedAt,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

